   134	/**
   135	 * @brief The thread used to read rx audio data and write to tx device (Loopback test).
   136	 */
   137	static void audprc_rx_tx_entry(void *param)
   138	{
   139	    rt_uint32_t evt;
   140	    rt_size_t len;
   141	
   142	    rt_kprintf("%s\n", __func__);
   143	    memset(g_audrx_buf, 0, sizeof(g_audrx_buf));
   144	    while (1)
   145	    {
   146	        rt_event_recv(g_rx_ev, 1, RT_EVENT_FLAG_OR | RT_EVENT_FLAG_CLEAR, RT_WAITING_FOREVER, &evt);
   147	
   148	        /* RX read (from mic)*/
   149	        len = rt_device_read(g_audprc_dev, 0, g_pipe_data, (AUDIO_BUF_SIZE / 2));
   150	        // rt_kprintf("len = %d\n", len);
   151	        if (len != (AUDIO_BUF_SIZE / 2))
   152	        {
   153	            rt_kprintf("Got abnormal audio size = %d\n", len);
   154	        }
   155	
   156	        /* TX write (to speaker)*/
   157	        len = rt_device_write(g_audprc_dev, 0, g_pipe_data, (AUDIO_BUF_SIZE / 2));
   158	        if (len != (AUDIO_BUF_SIZE / 2))
   159	        {
   160	            rt_kprintf("Write abnormal size = %d\n", len);
   161	        }
   162	
   163	    }
   164	}
   165	
   166	/**
   167	 * @brief The thread used to read rx audio data and save to the ram buffer,
   168	 *        the ram buffer'size is up to AUDIORX_BUF_MAX.
   169	 */
   170	static void audprc_rx_entry(void *param)
   171	{
   172	    rt_uint32_t evt;
   173	    rt_size_t len;
   174	
   175	    rt_kprintf("%s\n", __func__);
   176	    g_tmp_pos = 0;
   177	    memset(g_audrx_buf, 0, sizeof(g_audrx_buf));
   178	
   179	    while (1)
   180	    {
   181	        rt_event_recv(g_rx_ev, 1, RT_EVENT_FLAG_OR | RT_EVENT_FLAG_CLEAR, RT_WAITING_FOREVER, &evt);
   182	
   183	        /* RX read (from mic)*/
   184	        len = rt_device_read(g_audprc_dev, 0, g_pipe_data, AUDIO_BUF_SIZE / 2); //AUDIO_BUF_SIZE/2
   185	        if (len != (AUDIO_BUF_SIZE / 2))
   186	        {
   187	            rt_kprintf("Got abnormal audio size = %d\n", len);
   188	        }
   189	
   190	        /* Save to RAM Buffer. */
   191	        if ((g_tmp_pos + (AUDIO_BUF_SIZE / 2)) < AUDRX_BUF_MAX)
   192	        {
   193	            memcpy(&g_audrx_buf[g_tmp_pos], g_pipe_data, AUDIO_BUF_SIZE / 2);
   194	            g_tmp_pos += (AUDIO_BUF_SIZE / 2);
   195	        }
   196	        else
   197	        {
   198	            /* Record buffer is up to  AUDRX_BUF_MAX. Stop recording. */
   199	            goto __EXIT;
   200	        }
   201	
   202	    }
   203	
   204	__EXIT:
   205	    rt_kprintf("Record finished.\n");
   206	    rt_sem_release(complete_sem);
   207	}
   208	
   209	/**
   210	 * @brief The thread used to read audio data from ram buffer, and then write to tx device (speaker).
   211	 */
   212	static void audprc_tx_entry(void *param)
   213	{
   214	    rt_uint32_t evt;
   215	    uint32_t wr_offset = 0;
   216	
   217	    rt_kprintf("%s\n", __func__);
   218	
   219	    while (1)
   220	    {
   221	        rt_event_recv(g_tx_ev, 1, RT_EVENT_FLAG_OR | RT_EVENT_FLAG_CLEAR, RT_WAITING_FOREVER, &evt);
   222	
   223	        int len = rt_device_write(g_audprc_dev, 0, &g_audrx_buf[wr_offset], AUDIO_BUF_SIZE / 2);
   224	        if (len != (AUDIO_BUF_SIZE / 2))
   225	        {
   226	            rt_kprintf("Abnormal write len :%d\n", len);
   227	        }
   228	        wr_offset += (AUDIO_BUF_SIZE / 2);
   229	        if (wr_offset + (AUDIO_BUF_SIZE / 2)  >= AUDRX_BUF_MAX)
   230	        {
   231	            goto __EXIT;
   232	        }
   233	    }
   234	
   235	__EXIT:
   236	    rt_kprintf("Play finished.\n");
   237	    rt_sem_release(complete_sem);
   238	}
