   240	/**
   241	 * @brief Configuration RX (ADC) for AUDCODEC and AUDPRC.
   242	 */
   243	static void config_rx(rt_uint32_t channels, rt_uint32_t sr, rt_uint32_t fmt)
   244	{
   245	    struct rt_audio_caps caps;
   246	    int stream;
   247	
   248	    /* AUDCODEC : set input as "AUDPRC_RX_FROM_CODEC" */
   249	    rt_device_control(g_audcodec_dev, AUDIO_CTL_SETINPUT, (void *)AUDPRC_RX_FROM_CODEC);
   250	    caps.main_type = AUDIO_TYPE_INPUT;
   251	    caps.sub_type = 1 << HAL_AUDCODEC_ADC_CH0; // ADC CH0
   252	    caps.udata.config.channels   = channels;    // channels
   253	    caps.udata.config.samplerate = sr; // sample rate
   254	    caps.udata.config.samplefmt = fmt; // depth. 8 16 24 or 32
   255	    rt_device_control(g_audcodec_dev, AUDIO_CTL_CONFIGURE, &caps);
   256	
   257	    rt_kprintf("codec input parameter:sub_type=%d channels %d, rate %d, bits %d", caps.sub_type, caps.udata.config.channels,
   258	               caps.udata.config.samplerate, caps.udata.config.samplefmt);
   259	
   260	    /* AUDPRC : set input as "AUDPRC_RX_FROM_CODEC" */
   261	    rt_device_control(g_audprc_dev, AUDIO_CTL_SETINPUT, (void *)AUDPRC_RX_FROM_CODEC);
   262	    caps.main_type = AUDIO_TYPE_INPUT;
   263	    caps.sub_type = HAL_AUDPRC_RX_CH0 - HAL_AUDPRC_RX_CH0;
   264	    caps.udata.config.channels   = channels;
   265	    caps.udata.config.samplerate = sr;
   266	    caps.udata.config.samplefmt = fmt;
   267	    rt_kprintf("mic input:rx channel %d, channels %d, rate %d, bitwidth %d", 0, caps.udata.config.channels,
   268	               caps.udata.config.samplerate, caps.udata.config.samplefmt);
   269	    rt_device_control(g_audprc_dev, AUDIO_CTL_CONFIGURE, &caps);
   270	}
