   374	/**
   375	 * @brief Start TX and open PA.
   376	 */
   377	static void start_tx(rt_uint32_t samplerate)
   378	{
   379	    int stream_audprc, stream_audcodec;
   380	
   381	    rt_kprintf("%s\n", __func__);
   382	    rt_device_control(g_audcodec_dev, AUDIO_CTL_MUTE, (void *)1);
   383	    // rt_base_t level = rt_hw_interrupt_disable();
   384	    stream_audcodec = AUDIO_STREAM_REPLAY | ((1 << HAL_AUDCODEC_DAC_CH0) << 8);
   385	    stream_audprc   = AUDIO_STREAM_REPLAY | ((1 << HAL_AUDPRC_TX_CH0) << 8);
   386	
   387	    rt_device_control(g_audcodec_dev, AUDIO_CTL_START, &stream_audcodec);
   388	    rt_device_set_tx_complete(g_audprc_dev, audio_tx_done);
   389	    rt_device_control(g_audprc_dev, AUDIO_CTL_START, &stream_audprc);
   390	    // rt_hw_interrupt_enable(level);
   391	
   392	    /* Open PA. */
   393	    audio_pa_open(samplerate, 0);
   394	
   395	    rt_thread_mdelay(30);
   396	    rt_device_control(g_audcodec_dev, AUDIO_CTL_MUTE, (void *)0);
   397	}
