   407	    // rt_base_t level = rt_hw_interrupt_disable();
   408	    stream_audcodec = AUDIO_STREAM_REPLAY | ((1 << HAL_AUDCODEC_DAC_CH0) << 8);
   409	    stream_audprc   = AUDIO_STREAM_REPLAY | ((1 << HAL_AUDPRC_TX_CH0) << 8);
   410	    rt_device_control(g_audcodec_dev, AUDIO_CTL_STOP, &stream_audcodec);
   411	    rt_device_control(g_audprc_dev, AUDIO_CTL_STOP, &stream_audprc);
