   417	/**
   418	 * @brief Start TX and RX for AUDCODEC and AUDPRC.
   419	 */
   420	static void start_txrx(rt_uint32_t samplerate)
   421	{
   422	    int stream_audprc, stream_audcodec;
   423	
   424	    rt_kprintf("%s\n", __func__);
   425	    rt_device_control(g_audcodec_dev, AUDIO_CTL_MUTE, (void *)1);
   426	    // rt_base_t level = rt_hw_interrupt_disable();
   427	    stream_audcodec = AUDIO_STREAM_RXandTX | ((1 << HAL_AUDCODEC_ADC_CH0) << 8) | ((1 << HAL_AUDCODEC_DAC_CH0) << 8);
   428	    stream_audprc   = AUDIO_STREAM_RXandTX | ((1 << HAL_AUDPRC_RX_CH0) << 8) | ((1 << HAL_AUDPRC_TX_CH0) << 8);
   429	    rt_device_control(g_audcodec_dev, AUDIO_CTL_START, &stream_audcodec);
   430	    rt_device_set_tx_complete(g_audprc_dev, audio_tx_done);
   431	    rt_device_set_rx_indicate(g_audprc_dev, audio_rx_ind);
   432	    rt_device_control(g_audprc_dev, AUDIO_CTL_START, &stream_audprc);
   433	    // rt_hw_interrupt_enable(level);
   434	
   435	    /* Open PA */
   436	    audio_pa_open(samplerate, 0);
   437	    rt_thread_mdelay(30);
   438	    rt_device_control(g_audcodec_dev, AUDIO_CTL_MUTE, (void *)0);
   439	}
