   441	/**
   442	 * @brief Stop TX and RX , and close PA.
   443	 */
   444	static void stop_txrx(void)
   445	{
   446	    int stream_audprc, stream_audcodec;
   447	
   448	    stream_audcodec = AUDIO_STREAM_RXandTX | ((1 << HAL_AUDCODEC_ADC_CH0) << 8) | ((1 << HAL_AUDCODEC_DAC_CH0) << 8);
   449	    stream_audprc   = AUDIO_STREAM_RXandTX | ((1 << HAL_AUDPRC_RX_CH0) << 8) | ((1 << HAL_AUDPRC_TX_CH0) << 8);
   450	    rt_device_control(g_audcodec_dev, AUDIO_CTL_STOP, &stream_audcodec);
   451	    rt_device_control(g_audprc_dev, AUDIO_CTL_STOP, &stream_audprc);
   452	    /* Close PA */
   453	    audio_pa_close();
   454	}
