     2	# Audprc/Audcodec Audio Device
     3	The chip contains Audprc and Audcodec. Audprc is used for digital processing, while Audcodec is for digital-to-analog conversion.
     4	The common audio data flow is Audprc --> Audcodec --> Speaker.
     5	Another possible configuration is Audprc --> I2S --> External Codec chip.
     6	Main functionalities include:
     7	- Input and output sample rate settings
     8	- Input and output channel count settings
     9	- Bit depth setting for each sample
    10	- Volume control settings
    11	
    12	The playback code explanation, with specific examples, can be found in the `drv_audprc.c` file and the `example/rt_device/audprc` directory.
    13	
    14	```c
    15	static rt_event_t g_tx_ev;
    16	
    17	static rt_err_t speaker_tx_done(rt_device_t dev, void *buffer)
    18	{
    19	    // This function is called when one frame of data has been sent, through a DMA interrupt.
    20	    rt_event_send(g_tx_ev, 1);
    21	    return RT_EOK;
    22	}
    23	#define DMA_BUF_SIZE    1600
    24	
    25	void test_demo()
    26	{
    27	    g_tx_ev = rt_event_create("audio_tx_evt", RT_IPC_FLAG_FIFO);
    28	    // 1. Open devices
    29	    int err;
    30	    rt_device_t audprc_dev;
    31	    rt_device_t audcodec_dev;
    32	    audprc_dev = rt_device_find("audprc");
    33	    audcodec_dev = rt_device_find("audcodec");
    34	    RT_ASSERT(audprc_dev && audcodec_dev);
    35	
    36	    err = rt_device_open(audprc_dev, RT_DEVICE_FLAG_RDWR);
    37	    RT_ASSERT(RT_EOK == err);
    38	    err = rt_device_open(audcodec_dev, RT_DEVICE_FLAG_WRONLY);
    39	    RT_ASSERT(RT_EOK == err);
    40	
    41	    // 2. Set the callback for transmission completion
    42	    rt_device_set_tx_complete(audprc_dev, speaker_tx_done);
    43	    
    44	    // 3. Set the size of one DMA buffer, the underlying driver uses two such buffers for ping-pong buffering
    45	    rt_device_control(audprc_dev, AUDIO_CTL_SET_TX_DMA_SIZE, (void *)DMA_BUF_SIZE);
    46	
    47	    // 4. Output audio to the codec, if using I2S, set AUDPRC_TX_TO_I2S
    48	    rt_device_control(audcodec_dev, AUDIO_CTL_SETOUTPUT, (void *)AUDPRC_TX_TO_CODEC);
    49	    rt_device_control(audprc_dev,   AUDIO_CTL_SETOUTPUT, (void *)AUDPRC_TX_TO_CODEC);
    50	    
    51	    // 5. Configure codec parameters
    52	    struct rt_audio_caps caps;
    53	
    54	    caps.main_type = AUDIO_TYPE_OUTPUT;
    55	    caps.sub_type = (1 << HAL_AUDCODEC_DAC_CH0);
    56	#if BSP_ENABLE_DAC2
    57	    caps.sub_type |= (1 << HAL_AUDCODEC_DAC_CH1);
    58	#endif
    59	    caps.udata.config.channels   = 1; // Final output with one channel
    60	    caps.udata.config.samplerate = 16000; // Sample rate, options: 8000/11025/12000/16000/22050/24000/32000/44100/48000
    61	    caps.udata.config.samplefmt = 16; // Bit depth: 8, 16, 24, or 32
    62	    rt_device_control(audcodec_dev, AUDIO_CTL_CONFIGURE, &caps);
    63	    
    64	    struct rt_audio_sr_convert cfg;
    65	    cfg.channel = 2; // Source data channels, if 2, data will be in interleave format: LRLRLR...
    66	    cfg.source_sr = 16000; // Source data sample rate
    67	    cfg.dest_sr = 16000;   // Output sample rate  
    68	    rt_device_control(audprc_dev, AUDIO_CTL_OUTPUTSRC, (void *)(&cfg));
    69	
    70	    // Data selection. For a single source, this configuration is sufficient. For multiple sources, refer to the "Audio Path Mix & Mux Function Explanation" document.
    71	    caps.main_type = AUDIO_TYPE_SELECTOR;
    72	    caps.sub_type = 0xFF;
    73	    caps.udata.value = 0x5050;
    74	    rt_device_control(audprc_dev, AUDIO_CTL_CONFIGURE, &caps);
    75	    caps.main_type = AUDIO_TYPE_MIXER;
    76	    caps.sub_type = 0xFF;
    77	    caps.udata.value   = 0x5050;
    78	    rt_device_control(audprc_dev, AUDIO_CTL_CONFIGURE, &caps);
    79	
    80	    // Source data format specification
    81	    caps.main_type = AUDIO_TYPE_OUTPUT;
    82	    caps.sub_type = HAL_AUDPRC_TX_CH0;
    83	    caps.udata.config.channels   = 2;
    84	    caps.udata.config.samplerate = 16000;
    85	    caps.udata.config.samplefmt = 16;
    86	    rt_device_control(audprc_dev, AUDIO_CTL_CONFIGURE, &caps);
    87	
    88	    // Set the volume from the EQ configuration table to the codec. vol_level ranges from 0 to 15
    89	    uint8_t vol_level = 15;
    90	    int volumex2 = eq_get_music_volumex2(vol_level);
    91	    if (caps.udata.config.samplerate == 16000 || caps.udata.config.samplerate == 8000)
    92	       volumex2 = eq_get_tel_volumex2(vol_level);
    93	    rt_device_control(audcodec_dev, AUDIO_CTL_SETVOLUME, (void *)volumex2);
    94	
    95	    // Start playback
    96	    int stream = AUDIO_STREAM_REPLAY | ((1 << HAL_AUDPRC_TX_CH0) << 8);
    97	    rt_device_control(audprc_dev, AUDIO_CTL_START, (void *)&stream);
    98	    stream = AUDIO_STREAM_REPLAY | ((1 << HAL_AUDCODEC_DAC_CH0) << 8);
    99	    rt_device_control(audcodec_dev, AUDIO_CTL_START, &stream);
   100	    rt_uint32_t evt;
   101	    int16_t tx_pipe_data[4096];
   102	    while (1)
   103	    {
   104	        rt_event_recv(g_tx_ev, 1, RT_EVENT_FLAG_OR | RT_EVENT_FLAG_CLEAR, RT_WAITING_FOREVER, &evt);
   105	#if 1
   106	        rt_device_write(audprc_dev, 0, tx_pipe_data, DMA_BUF_SIZE);
   107	#else
   108	        // Faster alternative:
   109	        bf0_audprc_device_write(audprc_dev, 0, tx_pipe_data, DMA_BUF_SIZE);
   110	#endif
   111	    }
   112	    rt_device_close(audcodec_dev);
   113	    rt_device_close(audprc_dev);
   114	    rt_event_delete(g_tx_ev);
   115	}
